        let mut c1 = contents.clone();
        if unsafe { simd_json::from_str::<EncryptedState>(&mut c1) }.is_ok() {
            return Ok(true);
        }

        // Try to parse as plain state
        let mut c2 = contents;
        if unsafe { simd_json::from_str::<State>(&mut c2) }.is_ok() {
            return Ok(false);
        }

        bail!("Unknown state file format");
    }

